#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>

typedef struct Pair Pair;
struct Pair {
    int a,b;
};

unsigned int gcd(unsigned int a, unsigned int b) {
    return b ? gcd(b, a % b) : a;
}

int main(void) {
    Pair p = {84, 36};
    uint8_t small = 200;
    int64_t big = INT64_C(1) << 40;
    printf("gcd %d %d = %u\n", p.a, p.b, gcd(p.a, p.b));
    printf("u8 %u i64 %" PRId64 "\n", (unsigned int)small, big);
    return 0;
}
